{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spf_mp_final AS SELECT *, CASE WHEN UPPER(status) IN (\'APPROVED\', \'ACCEPT\', \'PAYMENT_COMPLETED\') THEN \'Approved\' WHEN UPPER(status) IN (\'REJECTED\', \'REJECT\') THEN \'Rejected\' WHEN UPPER(status) IN ( \'AWAITING_SELLER_RESPONSE\', \'INVOICE_CREATED\', \'CUSTOMER REPLIED\', \'INVOICE_INITIATED\', \'OPEN\', \'UNATTENDED\', \'AWAITING_AGENT_RESPONSE\' ) THEN \'pending\' ELSE \'pending\' END AS final_status, CASE WHEN UPPER(ISSUECATEGORY) = \'WRONG_RETURNS_RECEIVED_OTHER_SELLERS_PRODUCT\' THEN \'WPR\' WHEN UPPER(ISSUECATEGORY) = \'STAINED_RETURN\' THEN \'damage\' WHEN UPPER(ISSUECATEGORY) = \'SHORTAGE_IN_RETURN\' THEN \'short qty\' WHEN UPPER(ISSUECATEGORY) = \'DIFFERENT BRAND PRODUCT RECEIVED\' THEN \'Fake\' WHEN UPPER(ISSUECATEGORY) = \'DAMAGE PRODUCT RECEIVED\' THEN \'damage\' WHEN UPPER(ISSUECATEGORY) = \'DAMAGED_RETURN\' THEN \'damage\' WHEN UPPER(ISSUECATEGORY) = \'FAKE_RETURN\' THEN \'Fake\' WHEN UPPER(ISSUECATEGORY) = \'EMPTY BOX RECEIVED\' THEN \'short qty\' WHEN UPPER(ISSUECATEGORY) = \'SAME BRAND PRODUCT RECEIVED (ARTICLE NOT AS PER DOCUMENT)\' THEN \'WPR\' WHEN UPPER(ISSUECATEGORY) = \'PARTIAL ARTICLES RECEIVED\' THEN \'short qty\' WHEN UPPER(ISSUECATEGORY) = \'EMPTY_BOX\' THEN \'short qty\' WHEN UPPER(ISSUECATEGORY) = \'WRONG_RETURNS_RECEIVED_OWN_PRODUCT\' THEN \'WPR\' WHEN UPPER(ISSUECATEGORY) = \'SHORT QUANTITY\' THEN \'short qty\' ELSE \'other\' END AS reason_mapped, CASE WHEN UPPER(REJECTIONREASON) = \'SAME BRAND EQUAL PRICE\' THEN \'Same brand equal price\' WHEN UPPER(REJECTIONREASON) = \'WRONG SUBLINE\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'RAISED UNDER DIFF BRAND\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'OUT TAT\' THEN \'Out tat\' WHEN UPPER(REJECTIONREASON) = \'PENDING\' THEN \'pending\' WHEN UPPER(REJECTIONREASON) = \'VMS\' THEN \'VMS\' WHEN UPPER(REJECTIONREASON) = \'MASTERBAG ALREADY OPEN\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'VIDEO NOT SHARED\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'TAT BREACH\' THEN \'Out tat\' WHEN UPPER(REJECTIONREASON) = \'360 ROATATION ISSUE\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'CCTV ISSUE\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'TAMPERED\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'EAN-JIO\' THEN \'ean-jio\' WHEN UPPER(REJECTIONREASON) = \'REFURBISHABLE\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'FW TICKET REJECTION\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'ISC-NOT A VALID CLAIM\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'INVALID CLAIM\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'MULTIPLE REASONS\' THEN \'Multiple Reasons\' WHEN UPPER(REJECTIONREASON) = \'TAG LOOP NOT SCANNED\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'INCORRECT TAG LOOP\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'CUSTOMER RETURN REASON FOR WRONG AND DEFECTIVE\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'SAME BRAND\' THEN \'Same brand equal price\' WHEN UPPER(REJECTIONREASON) = \'PRODUCT NOT SHOWN IN VIDEO\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'NOT_ELIGIBLE_DUPLICATE_TAGLOOPID\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'PACKING ISSUE\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'NOT_ELIGIBLE_ITEM_NOT_DELIVERED_TO_SELLER\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'DAMAGE/USED PART NOT EVIDENT\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'STAINED DOESN\'\'T QUALIFY FOR REIMBURSEMENT\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'APPROVED\' THEN \'approved\' WHEN UPPER(REJECTIONREASON) = \'WFR\' THEN \'wfr\' WHEN UPPER(REJECTIONREASON) = \'DUPLICATE\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'NOT_ELIGIBLE_SKU_NOT_FOUND_FOR_SELLER\' THEN \'Invalid claim\' WHEN UPPER(REJECTIONREASON) = \'NOT_ELIGIBLE_TICKET_RAISED_BEYOND_14_DAYS_TAT\' THEN \'Out tat\' WHEN UPPER(REJECTIONREASON) = \'VIDEO NOT CLEAR/MISSING\' THEN \'video issue\' WHEN UPPER(REJECTIONREASON) = \'SAME BRAND HIGHER MRP\' THEN \'Same brand equal price\' WHEN UPPER(REJECTIONREASON) = \'REJECT - NO RESPONSE FROM SELLER\' THEN \'Reject - No response from seller\' ELSE \'other\' END AS final_rejection_reason, CASE WHEN CREATEDON LIKE \'%T%\' THEN TO_CHAR(TO_TIMESTAMP_TZ(CREATEDON), \'Mon\') WHEN CREATEDON LIKE \'%-%\' THEN TO_CHAR( TO_TIMESTAMP(CREATEDON, \'DD-MM-YYYY\'), \'Mon\') ELSE TO_CHAR(TO_TIMESTAMP(CREATEDON, \'DD/MM/YYYY\'), \'Mon\') END AS month FROM spf_mp;",
